{
  "selections": [
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '혼자 결정해야 할 때 어떤 느낌이 드시나요'라고 질문한 것은 손상된 자율성 스키마를 직접 탐색하는 것으로, 내담자가 '혼자 결정하는 것도 잘 못해요. 그냥 정해주는 게 편하니까요'라고 답한 것과 연결됨. 성장 경험에서 형과 비교당하며 스스로 선택할 기회를 갖지 못한 배경이 이 스키마의 기원."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "혼자 결정한다는 것은 자기 선택에 책임을 지는 것이며, 그 결과가 실패하면 '내가 무능하다'는 것이 완전히 증명된다는 가정이 자율적 결정을 두려움으로 만듦. 성장 경험에서 노력해도 '형만 못하다'는 반응이 반복된 것이 이 가정의 근거."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/1"],
      "relevance": "전력을 다해 스스로 결정했는데 실패하면 밑바닥 능력이 드러난다는 태도가, 혼자 결정하는 순간에 압박감이나 공포를 유발할 수 있음. 상황 사례에서 아버지가 '이번에는 되는 거냐'고 물을 때 '알아서 할게요'라고 답한 뒤 방에 들어가 문을 잠근 행동은 자율적 결정을 요구받는 순간의 회피를 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/childhood_data"],
      "relevance": "타인이 정해주는 쪽을 선택하면 결과가 안 좋아도 '내가 진짜로 한 게 아니다'라고 여길 수 있어 덜 비참하다는 가정이, '정해주는 게 편하다'는 내담자의 진술과 직접 연결됨. 성장 경험에서 시험 전날 공부를 안 하는 습관이 이 전략의 원형."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/3"],
      "relevance": "'나는 남들만큼 해내지 못하고 결국 실패할 것이다'라는 핵심 신념이, 혼자 결정해야 하는 순간에 '결정해도 어차피 안 될 텐데'라는 체념이나 공포로 나타날 수 있음. 상황 사례에서 '3년을 했는데 이 모양이면 머리 자체가 안 되는 거야'라는 자동 사고가 같은 신념의 표현."
    }
  ]
}

